import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Reseller Payouts — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Reseller Payouts — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/reseller-payouts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Reseller Payouts — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/reseller-payouts"}]]},"headers":[],"relativePath":"user-guide/reseller-payouts.md","filePath":"user-guide/reseller-payouts.md","lastUpdated":1786199211000}'),s={name:"user-guide/reseller-payouts.md"};function l(i,e,d,n,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="reseller-payouts-—-user-guide" tabindex="-1">Reseller Payouts — User Guide <a class="header-anchor" href="#reseller-payouts-—-user-guide" aria-label="Permalink to &quot;Reseller Payouts — User Guide&quot;">​</a></h1><h2 id="who-can-use-reseller-payouts" tabindex="-1">Who can use Reseller Payouts <a class="header-anchor" href="#who-can-use-reseller-payouts" aria-label="Permalink to &quot;Who can use Reseller Payouts&quot;">​</a></h2><p>Your workspace must have <strong>Reseller Payouts</strong> installed (requires <strong>Resellers</strong>, which requires <strong>Payments</strong>). Your role needs <code>reseller-payouts.view</code> to list entries, plus <code>approve</code> / <code>pay</code> / <code>void</code> for actions.</p><p>Without <code>resellers.assign</code> (and not superadmin), you only see entries where you are the party user, or entries for a reseller linked to your login.</p><p>Invited <strong>reseller</strong> role users can view their commission entries — not approve, pay, or void.</p><h2 id="how-commission-appears" tabindex="-1">How commission appears <a class="header-anchor" href="#how-commission-appears" aria-label="Permalink to &quot;How commission appears&quot;">​</a></h2><ol><li>Create a reseller with commission rates</li><li>Link that reseller on a customer invoice (<code>reseller_id</code>)</li><li>Collect payment until the invoice status is fully <strong>Paid</strong> (not Partial)</li><li>Two ledger rows appear with status <strong>Accrued</strong> — one for the reseller party, one for the owner party</li></ol><p>If Reseller Payouts is not installed when the invoice becomes Paid, no rows are created. Rows are not backfilled automatically later.</p><h2 id="list-kpis" tabindex="-1">List &amp; KPIs <a class="header-anchor" href="#list-kpis" aria-label="Permalink to &quot;List &amp; KPIs&quot;">​</a></h2><ul><li>Search by reseller name/email/company or invoice number/title</li><li>Filter by status (<code>accrued</code>, <code>approved</code>, <code>paid</code>, <code>void</code>), party (<code>reseller</code> | <code>owner</code>), and reseller</li><li>Stats: counts per status plus accrued / approved / paid amounts</li></ul><h2 id="approve-pay-void" tabindex="-1">Approve, pay, void <a class="header-anchor" href="#approve-pay-void" aria-label="Permalink to &quot;Approve, pay, void&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>From status</th><th>Permission</th></tr></thead><tbody><tr><td>Approve</td><td>Accrued only</td><td><code>reseller-payouts.approve</code></td></tr><tr><td>Mark paid</td><td>Approved only</td><td><code>reseller-payouts.pay</code></td></tr><tr><td>Void</td><td>Accrued or Approved (not Paid)</td><td><code>reseller-payouts.void</code></td></tr></tbody></table><p><strong>Mark paid</strong> records that the workspace has settled the commission — it does not move money through a payment gateway.</p><p>If a Paid invoice later leaves Paid (e.g. payment voided), <strong>all</strong> non-void ledger rows for that invoice are auto-voided (including ones already marked paid). If the invoice becomes Fully Paid again, those void rows are <strong>revived</strong> to accrued with updated amount snapshots. The manual <strong>Void</strong> action still rejects entries that are already <code>paid</code>.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><ul><li><a href="/user-guide/resellers">Resellers</a> — partner directory and rates</li><li><a href="/user-guide/payments">Payments</a> / <a href="/user-guide/invoices">Invoices</a> — invoice must be fully Paid to accrue</li></ul>',16)])])}const h=t(s,[["render",l]]);export{m as __pageData,h as default};
